pub type AuthError = enum {
  InvalidEmail,
  WeakPassword(min_len: Int),
  UserNotFound,
} derive[Debug]

fn AuthError.message(self: &AuthError) -> Str {
  match self {
    InvalidEmail => { return "Invalid email address"; }
    WeakPassword(min) => { return "Password must be at least " + min + " chars"; }
    UserNotFound => { return "User not found"; }
  }
}

fn validate_email(email: Str) -> Result[Str, AuthError] {
  if email.len() > 3 { return Ok(email); }
  return Err(AuthError.InvalidEmail);
}

fn validate_password(pw: Str) -> Result[Str, AuthError] {
  if pw.len() >= 8 { return Ok(pw); }
  return Err(AuthError.WeakPassword(8));
}

fn register(email: Str, pw: Str) -> Result[Str, AuthError] {
  let e = validate_email(email)?;
  let p = validate_password(pw)?;
  return Ok("Registered: " + e);
}

fn main() -> Int {
  match register("user@test.com", "password123") {
    Ok(_) => { return 1; }
    Err(_) => { return 0; }
  }
}
